/**
 * CLEAN-05 — generated-artifact freshness gate.
 *
 * NOTE: no `#!` line — this module is imported by
 * `web/src/__tests__/qualityGates.contract.test.ts` so the dirty-worktree
 * mutation fixture exercises the real snapshot/compare helpers.
 *
 * Every committed generated file in this repository must be reproducible from
 * its source, and proving that must NOT change the worktree. Before this gate
 * existed, `npm run prebuild` / `npm run predev` re-ran `buildChangelog.mjs` in
 * write mode on every build, so a build could silently rewrite a committed
 * source file and a developer (or CI) would ship a tree that never matched the
 * commit that produced it.
 *
 * What this enforces, driven by `scripts/generated-artifacts.json`:
 *
 *   1. COVERAGE     every git-tracked file carrying a generation marker in its
 *                   first lines is claimed by exactly one registry entry, so a
 *                   new generator cannot land unregistered and ungated.
 *   2. FRESHNESS    every registry entry with a `check` command runs it. A
 *                   stale artifact fails with the entry's `regenerate` hint.
 *   3. NON-MUTATION every registered output path is CONTENT-DIGESTED (sha-256,
 *                   recursive, deterministic order) before and after the run,
 *                   and `git status --porcelain` is captured alongside it.
 *
 * Why digests and not just `git status`: porcelain reports a *status code*, not
 * content. In a dirty worktree — the normal state of a feature branch — a file
 * that is already ` M` stays ` M` no matter how many times a "check" rewrites
 * it, and an already-`??` file stays `??`. The original status-only comparison
 * was therefore blind to exactly the case it was written to catch: a generator
 * silently rewriting an artifact somebody was already editing. Digests catch
 * the byte change; porcelain still catches brand-new undeclared paths that no
 * registry entry would have digested.
 *
 * Usage:
 *   node scripts/check-generated-freshness.mjs            # coverage + all checks
 *   node scripts/check-generated-freshness.mjs --coverage-only
 *   node scripts/check-generated-freshness.mjs --list
 *
 * Exit 0 = registry complete, artifacts current, worktree untouched.
 */
import { spawnSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import { lstatSync, readFileSync, readdirSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url))
const REPO_ROOT = resolve(SCRIPT_DIR, '..')
const REGISTRY_PATH = resolve(SCRIPT_DIR, 'generated-artifacts.json')

const COVERAGE_ONLY = process.argv.includes('--coverage-only')
const LIST_ONLY = process.argv.includes('--list')

// Only the first few lines count: generator SOURCES mention these strings too
// (they emit the banner), and so do tests that assert on it. A real generated
// artifact carries the banner at the very top of the file.
const MARKER_SCAN_LINES = 3
const MARKER_RE = /AUTOGENERATED|Code generated by[^\n]*DO NOT EDIT/
const MARKER_EXTENSIONS = ['.go', '.ts', '.tsx', '.mjs', '.js', '.json', '.yaml', '.yml', '.sql']

function git(args) {
  const result = spawnSync('git', args, { cwd: REPO_ROOT, encoding: 'utf8' })
  if (result.status !== 0) {
    throw new Error(`git ${args.join(' ')} failed: ${result.stderr || result.stdout}`)
  }
  return result.stdout
}

function porcelain() {
  // `-uall` so a generator that creates a brand-new untracked file is caught
  // too, not just one that edits a tracked file.
  return git(['status', '--porcelain', '-uall'])
}

function trackedFiles() {
  return git(['ls-files', '-z']).split('\0').filter(Boolean)
}

// ── Content-digest snapshot ─────────────────────────────────────────────────

/**
 * Marker for one path. `f:<sha256>` for a regular file, `d` for a directory,
 * `missing` when absent, `other:<kind>` for anything else (symlink, socket…).
 * The type is part of the marker so a file replaced by a directory — or by a
 * symlink to somewhere else — is a detected change, not a silent pass.
 */
export function pathMarker(absolutePath) {
  let stat
  try {
    stat = lstatSync(absolutePath)
  } catch {
    return 'missing'
  }
  if (stat.isDirectory()) return 'd'
  if (!stat.isFile()) return `other:${stat.isSymbolicLink() ? 'symlink' : 'special'}`
  return `f:${createHash('sha256').update(readFileSync(absolutePath)).digest('hex')}`
}

/** Recursive, deterministically ordered listing of relative paths under `dir`. */
export function listRecursive(absoluteDir) {
  const out = []
  const walk = (rel) => {
    const here = rel === '' ? absoluteDir : resolve(absoluteDir, rel)
    let entries
    try {
      entries = readdirSync(here, { withFileTypes: true })
    } catch {
      return
    }
    // Sort by name so the snapshot is stable across filesystems.
    for (const entry of [...entries].sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))) {
      const childRel = rel === '' ? entry.name : `${rel}/${entry.name}`
      out.push(childRel)
      if (entry.isDirectory()) walk(childRel)
    }
  }
  walk('')
  return out
}

/**
 * Digest every registered output path. Registry paths ending in `/` are
 * directories and are walked recursively so a generator cannot mutate one file
 * inside a claimed directory unnoticed.
 *
 * @param {string} root absolute repository root
 * @param {string[]} paths registry path strings
 * @returns {Record<string, string>} path → marker, insertion order deterministic
 */
export function snapshotRegisteredPaths(root, paths) {
  const snapshot = {}
  for (const declared of [...paths].sort()) {
    const absolute = resolve(root, declared)
    snapshot[declared] = pathMarker(absolute)
    if (!declared.endsWith('/')) continue
    if (snapshot[declared] !== 'd') continue
    for (const child of listRecursive(absolute)) {
      snapshot[`${declared}${child}`] = pathMarker(resolve(absolute, child))
    }
  }
  return snapshot
}

/**
 * Compare two worktree states.
 *
 * @param {{porcelain: string, digests: Record<string,string>}} before
 * @param {{porcelain: string, digests: Record<string,string>}} after
 * @returns {string[]} human-readable mutations (empty = nothing changed)
 */
export function compareWorktreeState(before, after) {
  const changes = []

  const keys = [...new Set([...Object.keys(before.digests), ...Object.keys(after.digests)])].sort()
  for (const key of keys) {
    const from = before.digests[key]
    const to = after.digests[key]
    if (from === to) continue
    if (from === undefined) {
      changes.push(`${key}: created during the run (${to})`)
    } else if (to === undefined) {
      changes.push(`${key}: disappeared during the run (was ${from})`)
    } else {
      changes.push(`${key}: content changed (${from} -> ${to})`)
    }
  }

  // Porcelain still matters for paths NO registry entry declares: a generator
  // that writes somewhere unexpected would not be digested at all.
  if (before.porcelain !== after.porcelain) {
    const beforeLines = new Set(before.porcelain.split('\n'))
    for (const line of after.porcelain.split('\n')) {
      if (line && !beforeLines.has(line)) {
        changes.push(`undeclared worktree entry appeared: ${line}`)
      }
    }
    const afterLines = new Set(after.porcelain.split('\n'))
    for (const line of before.porcelain.split('\n')) {
      if (line && !afterLines.has(line)) {
        changes.push(`worktree entry disappeared: ${line}`)
      }
    }
  }

  return changes
}

/**
 * Every path any registry entry claims — BOTH the generated outputs and the
 * inputs they are generated from.
 *
 * Sources matter as much as outputs. `split-i18n-catalog.mjs --check` reads
 * `src/i18n/en.json` and `known-missing-keys.json`; a "check" that repaired one
 * of those in place would be mutating the worktree just as surely as if it had
 * rewritten a generated file, and — because those inputs are routinely already
 * dirty on a feature branch — neither `git status` nor an output-only digest
 * would have noticed.
 *
 * Registry `sources` may name paths outside the repository conventions or
 * directories that do not exist for a given entry; `pathMarker` records
 * `missing` for those, which is itself a value worth comparing.
 */
export function registeredPaths(registry) {
  const paths = new Set()
  for (const artifact of registry.artifacts) {
    for (const p of artifact.paths ?? []) paths.add(p)
    for (const p of artifact.sources ?? []) paths.add(p)
  }
  return [...paths]
}

function loadRegistry() {
  const registry = JSON.parse(readFileSync(REGISTRY_PATH, 'utf8'))
  const seen = new Set()
  for (const artifact of registry.artifacts) {
    if (!artifact.id) throw new Error('registry entry without an id')
    if (seen.has(artifact.id)) throw new Error(`duplicate registry id: ${artifact.id}`)
    seen.add(artifact.id)
    if (!Array.isArray(artifact.paths) || artifact.paths.length === 0) {
      throw new Error(`registry entry ${artifact.id} declares no paths`)
    }
    if (!artifact.check && !artifact.checkOwner) {
      throw new Error(
        `registry entry ${artifact.id} has neither a non-mutating \`check\` command `
        + 'nor a documented `checkOwner` — every generated artifact must be gated somewhere',
      )
    }
  }
  return registry
}

/** True when `file` is claimed by a registry path (exact file or `dir/` prefix). */
function claimedBy(registry, file) {
  for (const artifact of registry.artifacts) {
    for (const p of artifact.paths) {
      if (p.endsWith('/') ? file.startsWith(p) : file === p) return artifact.id
    }
  }
  return null
}

function checkCoverage(registry) {
  const failures = []
  const unclaimed = []

  for (const file of trackedFiles()) {
    if (!MARKER_EXTENSIONS.some((ext) => file.endsWith(ext))) continue
    let head
    try {
      head = readFileSync(resolve(REPO_ROOT, file), 'utf8').split('\n', MARKER_SCAN_LINES).join('\n')
    } catch {
      continue
    }
    if (!MARKER_RE.test(head)) continue
    if (!claimedBy(registry, file)) unclaimed.push(file)
  }

  for (const file of unclaimed) {
    failures.push(
      `${file} carries a generation marker but is not in scripts/generated-artifacts.json — `
      + 'add an entry with either a non-mutating `check` command or a documented `checkOwner`',
    )
  }

  // The reverse direction: a registry path that no longer exists is dead weight
  // that would silently stop gating anything.
  const tracked = new Set(trackedFiles())
  const trackedDirs = new Set()
  for (const file of tracked) {
    const parts = file.split('/')
    for (let i = 1; i < parts.length; i++) trackedDirs.add(`${parts.slice(0, i).join('/')}/`)
  }
  for (const artifact of registry.artifacts) {
    for (const p of artifact.paths) {
      const exists = p.endsWith('/') ? trackedDirs.has(p) : tracked.has(p)
      if (!exists) {
        failures.push(`registry entry ${artifact.id} points at ${p}, which is not tracked by git`)
      }
    }
  }

  console.log(
    `[generated] coverage: ${registry.artifacts.length} registry entries claim every `
    + `marked artifact (${unclaimed.length} unclaimed)`,
  )
  return failures
}

function runChecks(registry) {
  const failures = []
  for (const artifact of registry.artifacts) {
    if (!artifact.check) {
      console.log(`[generated] ${artifact.id.padEnd(28)} delegated → ${artifact.gate}`)
      continue
    }
    const { cwd, command } = artifact.check
    const result = spawnSync(command[0], command.slice(1), {
      cwd: resolve(REPO_ROOT, cwd ?? '.'),
      encoding: 'utf8',
    })
    const output = `${result.stdout ?? ''}${result.stderr ?? ''}`.trim()
    if (result.status === 0) {
      console.log(`[generated] ${artifact.id.padEnd(28)} OK`)
    } else {
      console.log(`[generated] ${artifact.id.padEnd(28)} STALE`)
      failures.push(
        `${artifact.id} is stale (${artifact.paths.join(', ')}).\n`
        + `      regenerate: ${artifact.regenerate ?? '(no regenerate command recorded)'}\n`
        + output.split('\n').map((l) => `      | ${l}`).join('\n'),
      )
    }
  }
  return failures
}

function main() {
  const registry = loadRegistry()

  if (LIST_ONLY) {
    for (const artifact of registry.artifacts) {
      console.log(`${artifact.id}\n  paths: ${artifact.paths.join(', ')}\n  gate:  ${artifact.gate}`)
    }
    return
  }

  const paths = registeredPaths(registry)
  const snapshot = () => ({
    porcelain: porcelain(),
    digests: snapshotRegisteredPaths(REPO_ROOT, paths),
  })

  const before = snapshot()

  const failures = [...checkCoverage(registry)]
  if (!COVERAGE_ONLY) failures.push(...runChecks(registry))

  const after = snapshot()
  const mutations = compareWorktreeState(before, after)
  if (mutations.length > 0) {
    failures.push(
      'a freshness check MUTATED the worktree — verification must never write.\n'
      + mutations.map((m) => `      | ${m}`).join('\n'),
    )
  } else {
    console.log(
      `[generated] non-mutation: ${Object.keys(before.digests).length} registered path(s) `
      + 'byte-identical, no undeclared worktree entries',
    )
  }

  if (failures.length > 0) {
    console.error('\n[generated] FAILURES:')
    for (const f of failures) console.error(`  - ${f}`)
    console.error('')
    process.exit(1)
  }

  console.log('\n[generated] OK — every committed generated artifact is registered and current\n')
}

// Only run the CLI when invoked directly, so the contract test can import the
// pure snapshot/compare helpers without triggering a process.exit.
if (process.argv[1] && resolve(process.argv[1]) === resolve(fileURLToPath(import.meta.url))) {
  main()
}
